CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `ecommerce_portfolio`.`vw_dashboard_ytd_kpi` AS with `yearly` as (select `ecommerce_portfolio`.`vw_valid_sales_orders`.`order_year` AS `order_year`,count(0) AS `total_orders`,count(distinct `ecommerce_portfolio`.`vw_valid_sales_orders`.`customer_id`) AS `total_customers`,sum(`ecommerce_portfolio`.`vw_valid_sales_orders`.`units_sold`) AS `total_units`,sum(`ecommerce_portfolio`.`vw_valid_sales_orders`.`sales_revenue`) AS `total_revenue` from `ecommerce_portfolio`.`vw_valid_sales_orders` where ((`ecommerce_portfolio`.`vw_valid_sales_orders`.`order_year` in (2024,2025)) and (`ecommerce_portfolio`.`vw_valid_sales_orders`.`order_month` between 1 and 11)) group by `ecommerce_portfolio`.`vw_valid_sales_orders`.`order_year`), `comparison` as (select `yearly`.`order_year` AS `order_year`,`yearly`.`total_orders` AS `total_orders`,`yearly`.`total_customers` AS `total_customers`,`yearly`.`total_units` AS `total_units`,`yearly`.`total_revenue` AS `total_revenue`,lag(`yearly`.`total_revenue`) OVER (ORDER BY `yearly`.`order_year` )  AS `previous_revenue`,lag(`yearly`.`total_orders`) OVER (ORDER BY `yearly`.`order_year` )  AS `previous_orders`,lag(`yearly`.`total_customers`) OVER (ORDER BY `yearly`.`order_year` )  AS `previous_customers`,lag(`yearly`.`total_units`) OVER (ORDER BY `yearly`.`order_year` )  AS `previous_units` from `yearly`) select `comparison`.`order_year` AS `order_year`,'Jan-Nov' AS `comparison_period`,round(`comparison`.`total_revenue`,2) AS `total_revenue`,`comparison`.`total_orders` AS `total_orders`,`comparison`.`total_customers` AS `total_customers`,`comparison`.`total_units` AS `total_units`,round((`comparison`.`total_revenue` / nullif(`comparison`.`total_orders`,0)),2) AS `aov`,round((`comparison`.`total_revenue` / nullif(`comparison`.`total_units`,0)),2) AS `avg_selling_price`,round((((`comparison`.`total_revenue` - `comparison`.`previous_revenue`) / nullif(`comparison`.`previous_revenue`,0)) * 100),2) AS `revenue_yoy_pct`,round((((`comparison`.`total_orders` - `comparison`.`previous_orders`) / nullif(`comparison`.`previous_orders`,0)) * 100),2) AS `orders_yoy_pct`,round((((`comparison`.`total_customers` - `comparison`.`previous_customers`) / nullif(`comparison`.`previous_customers`,0)) * 100),2) AS `customers_yoy_pct`,round((((`comparison`.`total_units` - `comparison`.`previous_units`) / nullif(`comparison`.`previous_units`,0)) * 100),2) AS `units_yoy_pct` from `comparison`